/// Calls `$m!(Enum, sys::SlangEnum)` for every enum above.
#[cfg(test)]
macro_rules! for_each_enum {
	($m:ident) => {
		$m!(BindingType, sys::SlangBindingType);
		$m!(CompileTarget, sys::SlangCompileTarget);
		$m!(DebugInfoLevel, sys::SlangDebugInfoLevel);
		$m!(DeclKind, sys::SlangDeclKind);
		$m!(FloatingPointMode, sys::SlangFloatingPointMode);
		$m!(ImageFormat, sys::SlangImageFormat);
		$m!(LayoutRules, sys::SlangLayoutRules);
		$m!(LineDirectiveMode, sys::SlangLineDirectiveMode);
		$m!(MatrixLayoutMode, sys::SlangMatrixLayoutMode);
		$m!(ModifierID, sys::SlangModifierID);
		$m!(OptimizationLevel, sys::SlangOptimizationLevel);
		$m!(ParameterCategory, sys::SlangParameterCategory);
		$m!(GenericArgType, sys::SlangReflectionGenericArgType);
		$m!(ResourceAccess, sys::SlangResourceAccess);
		$m!(ScalarType, sys::SlangScalarType);
		$m!(SourceLanguage, sys::SlangSourceLanguage);
		$m!(Stage, sys::SlangStage);
		$m!(TypeKind, sys::SlangTypeKind);
		$m!(CompilerOptionName, sys::slang_CompilerOptionName);
	};
}

#[cfg(test)]
pub(crate) use for_each_enum;
